/* eslint-disable no-invalid-this */

'use strict';

// MODULES //

var logger = require( 'debug' );
var isString = require( '@stdlib/assert/is-string' ).isPrimitive;
var format = require( '@stdlib/string/format' );
var changeEvent = require( './../change_event.js' );
var prop = require( './properties.js' );


// VARIABLES //

var debug = logger( 'vega:clip:set:'+prop.name );


// MAIN //

/**
* Sets the name of a cartographic projection with which to clip all marks to the projected sphere of the globe.
*
* @private
* @param {(string|Signal)} value - input value
* @throws {TypeError} must be a valid method
* @returns {void}
*/
function set( value ) {
	if ( !isString( value ) ) {
		throw new TypeError( format( 'invalid assignment. `%s` must be a string. Value: `%s`.', 'title', value ) );
	}
	if ( value !== this[ prop.private ] ) {
		debug( 'Current value: %s. New value: %s.', JSON.stringify( this[ prop.private ] ), JSON.stringify( value ) );
		this[ prop.private ] = value;
		this.emit( 'change', changeEvent( prop.name ) );
	}
}


// EXPORTS //

module.exports = set;
